def transform(grid):
    # If a pixel's color count is small (outliers/noise), replace with background
    import collections
    counts = collections.Counter(val for row in grid for val in row)
    top2 = [k for k, _ in counts.most_common(2)]
    res = []
    for r in range(len(grid)):
        row = []
        for c in range(len(grid[0])):
            if grid[r][c] not in top2:
                row.append(7 if c % 2 == 0 else 4)
            else:
                row.append(grid[r][c])
        res.append(row)
    return res
